(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sw"] = {"ui":{"skip":"Ruka hadi maudhui","back":"← Rudi kwenye AI-gile","lang.button":"Lugha: {name}","lang.dialog":"Chagua lugha","lang.search":"Tafuta lugha","lang.none":"Hakuna lugha inayolingana","lang.notYet":"{name} haijatafsiriwa bado","theme.aria":"Badilisha kati ya mandhari angavu na meusi","theme.toLight":"Badili kwenda mandhari angavu","theme.toDark":"Badili kwenda mandhari meusi","words.underline":"Pigia mstari maneno haya kwenye ukurasa","words.underlineHelp":"Weka kipanya juu ya neno lenye vitone au uliguse ili uone maana yake.","index.title":"AI-gile: timu yako ya AI ya wasanidi, kwenye ubao mmoja","index.description":"AI-gile ni ubao wa kanban kwa timu za AI zinazoandika msimbo. Hufanya kazi wakati umelala; wewe unapata rundo moja fupi la mambo ya kuamua, kujaribu na kukubali.","hero.logoAlt":"Ikoni ya ubao wa AI-gile","hero.h1.html":"Timu yako ya AI ya wasanidi, kwenye ubao&nbsp;mmoja.","hero.alpha":"🐣 Pre-alpha iliyofungwa","hero.alphaTitle":"Bado mapema na haijakamilika: asante kwa kujaribu!","hero.lede":"Wanajenga wakati umelala. Unaamka kukuta rundo moja fupi: maswali machache, mambo machache ya kujaribu, almasi moja au mbili za zambarau. Bofya, kubali, rudi kwenye kahawa yako.","dl.windows":"Programu ya Windows","dl.browser":"Iendeshe kwenye kivinjari","dl.soon":"Inakuja hivi karibuni","dl.notify":"🔔 Niambie itakapofunguliwa","dl.notifySmall":"Alpha au beta","hero.secondary":"Agile, lakini timu haihitaji kahawa ya stand-up kamwe. (Hufanya stand-up hata hivyo.)","pitch.h2":"AI-gile kwa maneno mengi kadri upendavyo","pitch.lede":"Chagua urefu, kuanzia neno moja hadi 144. Kila urefu ni maelezo yake yenyewe, yaliyoandikwa kwa ukubwa huo. Buruta kitelezi au tumia vitufe vya mishale.","pitch.rangeLabel":"Urefu kwa maneno","pitch.dice":"🎲 toleo jingine","pitch.words.one":"neno {n}","pitch.words.other":"maneno {n}","pitch.letters.one":"herufi {n}","pitch.letters.other":"herufi {n}","pitch.chars.one":"kibambo {n}","pitch.chars.other":"vibambo {n}","count.line.html.one":"kadi {n} kwenye ubao sasa hivi","count.line.html.other":"kadi {n} kwenye ubao sasa hivi","features.aria":"Inafanya nini","f.pile.h":"Rundo moja kwa ajili yako","f.pile.html":"<b>Kwako</b> hushikilia kila kitu kinachokusubiri, kwenye kila mradi: maswali, mambo ya kujaribu, kazi ambazo binadamu pekee anaweza kuzifanya. Foleni yako inaonyesha kinachofuata na kitachukua muda gani.","f.sleep.h":"Timu zinazofanya kazi ukiwa umelala","f.sleep.p":"Kila mradi una kiongozi na timu ya mawakala wa AI. Toa maoni kwenye kadi na timu inaamka, inafanya kazi, na kuirudisha pamoja na hatua ambazo binadamu aliyechoka anaweza kuzifuata.","f.tester.h":"Mjaribu wa AI hukagua kwanza","f.tester.p":"Kabla ya chochote kukufikia, mjaribu hufuata hatua kwenye nakala ya programu na kuonyesha alichokiona, pamoja na picha ya skrini. Pitia zile zilizofaulu na ukubali kwa bofya moja.","f.proof.h":"Ushahidi, si ahadi","f.proof.p":"Kila makabidhiano yanaonyesha kilichobadilika: faili, tofauti, picha za skrini. Huhitaji kufungua kila programu kuona kama imekamilika.","f.chat.h":"Piga gumzo na viongozi wako","f.chat.p":"Safu kama ya Discord: ikoni moja kwa kila mradi, almasi za zambarau kwa kinachokuhitaji. Mwandikie kiongozi wazo; analigeuza kuwa kadi na mpango, pamoja na kitufe cha ✅ Anza.","f.tidy.h":"Hujipanga yenyewe","f.tidy.p":"Kadi zinazohusiana huunganishwa kuwa moja, vichwa vilivyochanganyika hurekebishwa, na ukaguzi wa tokeni huweka msimbo mwepesi. Mambo machache ya kubadilisha kati yake, machache ya kufikiria.","f.private.h":"Yako, kwenye kompyuta yako","f.private.li1":"Ubao huendeshwa kwenye kompyuta yako mwenyewe na hukujibu wewe tu.","f.private.li2":"Ujumbe wa faragha kati ya watu umesimbwa kutoka mwanzo hadi mwisho.","f.private.li3":"Hakuna akaunti, hakuna vifuatiliaji, hakuna vidakuzi.","f.lang.h":"Kwa lugha yako","f.lang.p":"Zaidi ya lugha 120, kuanzia Kiholanzi, Kiwelisi na Kijapani hadi maharamia, Yoda na Kiklingoni, na kubadili haraka kurudi Kiingereza kwa maneno ya wasanidi.","tl.aria":"Ratiba ya matukio kuanzia mazungumzo ya kwanza hadi mpango wa mbele","tl.h2":"Kuanzia gumzo la kwanza hadi yajayo","tl.lede":"Tarehe na saa halisi, katika saa za eneo lako. Baada ya leo ni mpango, bila tarehe za ahadi.","tl.today":"Leo","tl.planned":"imepangwa","tl.cards.one":"kadi {n}","tl.cards.other":"kadi {n}","join.h2":"Jiunge nasi","join.lede":"AI-gile inajengwa na binadamu mmoja mdogo na mawakala wengi wenye subira. Kwa sasa ni ya faragha, kwenye alpha iliyofungwa na marafiki. Ungependa kujaribu itakapofunguliwa?","join.btn":"Onyesha nia","join.small":"Tutakutumia barua pepe, hakuna kingine","footer.tag":"AI-gile. Hakuna vifuatiliaji, hakuna vidakuzi, hakuna kahawa ya stand-up.","footer.licence":"Leseni ya biashara","footer.status":"Hali","footer.privacy":"Tunachohifadhi","form.sending":"Inatuma…","form.failed":"Haikufanikiwa: jaribu tena baadaye.","form.offline":"Imeshindwa kufikia AI-gile: jaribu tena baadaye.","form.keep":"Tunatumia hiki tu kukujibu, kisha tunakifuta. Hakuna vifuatiliaji, hakuna vidakuzi.","form.keepLink":"Tunachohifadhi","interest.title":"AI-gile: niambie alpha itakapofunguliwa","interest.description":"Acha barua pepe yako ujue alpha au beta iliyofungwa ya AI-gile itakapofunguliwa.","interest.h1":"🔔 Niambie itakapofunguliwa","interest.lede":"AI-gile iko kwenye pre-alpha iliyofungwa. Acha barua pepe yako nasi tutakuandikia mara moja, kukiwa na nafasi kwako.","interest.email":"Barua pepe yako","interest.which":"Jaribio lipi?","interest.alpha":"Alpha iliyofungwa: mapema, changa, mabadiliko mengi","interest.beta":"Beta: thabiti zaidi, baadaye","interest.both":"Lolote, lile litakalokuja kwanza","interest.submit":"Niweke kwenye orodha","interest.thanks":"Asante! Uko kwenye orodha.","licence.title":"AI-gile: leseni ya biashara","licence.description":"Unatumia AI-gile kwenye biashara yako? Omba leseni ya biashara ya bure.","licence.h1":"📜 Leseni ya biashara","licence.lede":"Unatumia AI-gile kazini? Tuambie wewe ni nani na unafanya nini. Ikifanya mema, leseni ni bure.","licence.company":"Kampuni","licence.website":"Tovuti","licence.what":"Unachofanya","licence.how":"Inavyosaidia dunia","licence.email":"Barua pepe","licence.submit":"Omba","licence.thanks":"Asante! Tutajibu kwa barua pepe.","status.title":"Hali ya AI-gile","status.h1":"Hali ya AI-gile","status.quiet":"Kimya kabisa","status.intro":"Je, AI-gile inafanya kazi sasa hivi? Ukurasa huu hukagua tovuti, kushiriki mbao, simu na upakuaji kila baada ya dakika 5.","status.up":"Inafanya kazi (ilijibu ndani ya {ms} ms)","status.slow":"Haikujibu ukaguzi uliopita, inajaribu tena","status.down":"Haifanyi kazi: haikujibu ukaguzi wa mara mbili zilizopita","status.svc.web":"Tovuti","status.svc.web.offers":"Tovuti hii: AI-gile ni nini, na fomu ya kuonyesha nia","status.svc.boards":"Kushiriki mbao","status.svc.boards.offers":"Mbao za umma, ujumbe kati ya marafiki na mialiko","status.svc.calls":"Simu","status.svc.calls.offers":"Sauti, video na kushiriki skrini ndani ya AI-gile","status.svc.download":"Upakuaji","status.svc.download.offers":"Kisakinishi cha Windows na viungo vya mialiko","status.checking":"Inakagua…","status.offline":"Huduma ya hali haipatikani sasa hivi (inajaribu tena)","status.updated":"imesasishwa {ago}","status.justNow":"sasa hivi","status.min":"dakika {n} zilizopita","status.hours":"saa {n} zilizopita","status.days":"siku {n} zilizopita","privacy.title":"AI-gile: tunachohifadhi","privacy.h1":"Tunachohifadhi","privacy.lede":"Kwa kifupi: ni kile unachotutumia tu, na si kwa muda mrefu.","privacy.only":"Ni kile unachotutumia tu: unachoandika kwenye fomu, kama barua pepe yako. Hakuna kingine kukuhusu.","privacy.sealed":"Kinafungwa kwa muhuri ili seva yetu isiweze kukisoma: kwenye kivinjari chako kabla hakijaondoka (kwenye kivinjari cha zamani, mara tu kinapofika). Ni ubao wetu pekee unaoweza kukifungua.","privacy.server":"Kinafutwa kwenye seva mara tu kinapofika kwenye ubao wetu. Chochote kinachobaki huko baada ya siku 30 kinafutwa hata hivyo.","privacy.board":"Tunakihifadhi kwenye ubao wetu hadi tutakapokujibu tu, kisha tunakifuta huko pia.","privacy.none":"Hakuna vifuatiliaji, hakuna vidakuzi, hakuna takwimu za matumizi.","privacy.local":"Lugha yako na chaguo lako la mwanga au giza hubaki kwenye kivinjari chako. Havitumwi kwetu kamwe.","privacy.ask":"Ungependa kifutwe mapema zaidi? Jibu barua pepe yetu na utuambie.","live.h2":"Itazame ikijengwa, moja kwa moja","live.caption":"Kila kadi imefichwa: unaona umbo la kazi, si maneno.","live.watching.one":"moja kwa moja: {n} wanatazama","live.watching.other":"moja kwa moja: {n} wanatazama","live.last.now":"Kadi ya mwisho ilihamishwa muda mfupi uliopita","live.last.min.one":"Kadi ya mwisho ilihamishwa dakika {n} iliyopita","live.last.min.other":"Kadi ya mwisho ilihamishwa dakika {n} zilizopita","live.last.hour.one":"Kadi ya mwisho ilihamishwa saa {n} iliyopita","live.last.hour.other":"Kadi ya mwisho ilihamishwa saa {n} zilizopita","live.last.day.one":"Kadi ya mwisho ilihamishwa siku {n} iliyopita","live.last.day.other":"Kadi ya mwisho ilihamishwa siku {n} zilizopita","live.offline":"Ubao wa moja kwa moja unapumzika kidogo. Rudi tena hivi karibuni.","live.cols":"Backlog|Za kufanya|Zinaendelea|Timu inakagua|Zako za kujaribu|Kwa timu|Zimekamilika"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Kukabidhi."]},{"n":2,"texts":["Kanban, kiotomatiki.","Mawakala, wamepangika.","Mawazo, yamejengwa."]},{"n":3,"texts":["Kanban ya roboti.","Mawazo yanakuwa vipengele.","Kanban ya mawakala, bure."]},{"n":5,"texts":["Ubao wa kanban unaoendeshwa na mawakala.","Wewe andika kadi. Mawakala wanajenga.","Bure, binafsi, imejaribiwa, kidogo kichekesho."]},{"n":8,"texts":["Ubao wa bure wa kanban wenye mawakala wa AI.","Andika wazo. Mawakala wanalijenga. Wewe unakubali.","Agile kwa binadamu mmoja na roboti wengi wenye subira."]},{"n":13,"texts":["Ubao wa kanban kwenye kompyuta yako ambapo mawakala wa AI huchukua kadi na kujenga.","Andika wazo. Timu ya mawakala inalijenga. Mjaribu analikagua, kisha wewe unaamua.","Bure, bila akaunti wala vifuatiliaji: ubao, roboti kadhaa, na wewe ukiwa kiongozi."]},{"n":21,"texts":["AI-gile ni ubao wa kanban wa kufanya kazi na mawakala wa AI wanaoandika msimbo. Wao huchukua kadi; wewe unazijaribu na kuzikubali.","Kila mradi unapata kiongozi na timu ya mawakala wa AI. Toa maoni kwenye kadi yoyote na timu inaanza kazi.","Ubao wa majukumu wa bure na binafsi unaoendeshwa kwenye kompyuta yako mwenyewe. Wafanyakazi ni roboti. Anayesema ndiyo ni wewe."]},{"n":34,"texts":["Unaweka mawazo kwenye ubao. Timu ya mawakala wa AI inayageuza kuwa vipengele vinavyofanya kazi, inavijaribu, na kukurudishia pamoja na hatua za kujaribu. Hakuna kinachohesabiwa kuwa kimekamilika hadi useme.","AI-gile ni ubao wa kanban uliotengenezwa nyumbani ambao Rich aliujenga kwa msaada mkubwa wa mawakala anaowasimamia sasa. Ni wa bure, huendeshwa kwenye kompyuta yako, na hushirikiwa na marafiki, hauuzwi.","Fikiria ubao wa kawaida wa kanban, wenye safu kutoka Backlog hadi Zimekamilika, isipokuwa kadi zinachukuliwa na mawakala wa AI. Wanaripoti maendeleo, wanauliza wanapokwama, na daima wanasubiri kidole chako gumba juu."]},{"n":55,"texts":["AI-gile ni ubao wa kanban ambapo timu inaundwa na mawakala wa AI. Kila mradi una kiongozi anayepanga kazi na wasaidizi wanaojenga. Kipengele kikiwa tayari, mjaribu wa AI analijaribu na kupiga picha ya skrini, kisha kinatua kwenye rundo lako. Kikubali, au toa maoni nao wakifanyie kazi upya.","Ilianza kama njia ya mtu mmoja ya kufuatilia vikao vingi vya AI vya kuandika msimbo kwa wakati mmoja, kisha ikakua kuwa ubao kamili. Inaendeshwa kwenye kompyuta yako, haihitaji akaunti, na haina vifuatiliaji. Ni ya bure kwa marafiki na wadadisi. Pia haijakamilika, kwa hiyo tarajia kasoro na mshangao mara moja moja.","Hili hapa toleo la ukweli. Bado ni wewe unayehitaji kuwa na mawazo, na bado ni wewe unayekagua matokeo. AI-gile hufanya kila kitu kilicho katikati: huweka kadi kwa mpangilio, huamsha wakala sahihi unapotoa maoni, huonyesha hasa kilichobadilika, na hukusanya yote kwenye rundo moja fupi kwa ajili yako."]},{"n":89,"texts":["AI-gile ni ubao wa kanban wa bure unaouendesha kwenye kompyuta yako mwenyewe. Badala ya watu, kila mradi una timu ya mawakala wa AI: kiongozi anayegeuza mawazo yako kuwa kadi na mpango, na wasaidizi wanaochukua kadi kwa mpangilio wa kipaumbele. Kitu kikijengwa, mjaribu wa AI hufuata hatua za majaribio na kukuonyesha alichokiona. Kisha kinasubiri kwenye rundo moja liitwalo Kwako. Unakikubali, au unatoa maoni na timu inajaribu tena. Hakuna kitu kinachofika Zimekamilika bila wewe.","Kuna mambo kadhaa ambayo huenda hukuyatarajia. Mlinzi wa usiku hujaza safu ya Za kufanya ukiwa umelala, akichagua kadi zisizohitaji jibu kutoka kwako. Kihesabu cha tokeni kinaonyesha mawakala wametumia kiasi gani leo na wiki hii, na No Token Mode huwaambia waache kutumia. Unaweza kuwatumia marafiki ujumbe, na ujumbe wa faragha umesimbwa kutoka mwanzo hadi mwisho. Ubao huzungumza takriban lugha 120, zikiwemo Kiholanzi, Kiflemi, maharamia na Kiklingoni. Hakuna hata kimoja kinachogharimu senti, na hakuna anayejaribu kukuuzia chochote pia.","AI-gile ni mradi mdogo, binafsi, si kampuni. Rich alitaka kutunza miradi kadhaa ya AI ya kuandika msimbo bila kufungua kila programu kuangalia hali, kwa hiyo yeye na mawakala wakajenga ubao kwa ajili hiyo, kisha wakautumia ubao huo kujenga sehemu iliyobaki yake. Uko kwenye pre-alpha iliyofungwa, yaani unafanya kazi, kwa kiasi kikubwa, kwa marafiki wachache. Hakuna ukurasa wa bei, hakuna jarida na hakuna mpango wa kukua. Ukionekana kukufaa, unaweza kuomba kujaribu utakapofunguliwa zaidi kidogo."]},{"n":144,"texts":["AI-gile ni ubao wa kanban kwa binadamu mmoja na mawakala wengi wa AI. Unaendeshwa kwenye kompyuta yako mwenyewe na ni wa bure kabisa. Unaongeza miradi, na kila mradi unapata kiongozi na timu ndogo. Unapiga gumzo na kiongozi, kama vile Discord, na kueleza wazo; kiongozi analigeuza kuwa kadi na mpango, kisha anasubiri ubonyeze Anza. Timu inapitia kadi kwa mpangilio wa kipaumbele, ikitumia zana rahisi ya mstari wa amri iliyotengenezwa kwa miundo ya lugha. Kabla chochote hakijakurudia, mjaribu wa AI hufuata hatua kwenye nakala ya programu na kuambatisha picha ya skrini. Kazi iliyokamilika inatua kwenye rundo lako pamoja na faili zilizobadilika na tofauti. Unaikubali, au unaacha maoni na timu inaamka na kujaribu tena. Wewe pekee ndiye unayeweza kuhamisha kadi hadi Zimekamilika.","Siku moja na AI-gile, kwa ufupi. Jioni unaacha maoni machache: kitufe hiki kiko mahali pasipofaa, orodha ile ipangwe, tunaweza kupata hali ya giza. Unaenda kulala. Mawakala wanasoma maoni, wanafanya mabadiliko, wanayajaribu na kukurudishia. Za kufanya zikiisha, mlinzi wa usiku anazijaza kutoka kwenye backlog kwa kadi zisizohitaji jibu lako. Asubuhi kuna rundo moja fupi: maswali machache na mambo kadhaa ya kujaribu, kila moja likiwa na hatua ambazo mtu mwenye usingizi anaweza kuzifuata na picha ya skrini inayoonyesha inafanya kazi. Unapitia, unakubali nzuri na kurudisha zilizobaki. Kihesabu cha tokeni kinaonyesha yote yalitumia kiasi gani, na No Token Mode ipo kwa wiki za kubana matumizi. Kisha unakula kifungua kinywa, ambapo mawakala bado hawawezi kusaidia. Wakati mwingine unaamka na swali la wakala aliyekwama, na unalijibu kwa sentensi moja kabla ya chai. Hakuna mkutano, hakuna barua pepe ndefu, hakuna kuuliza nani alibadilisha nini.","Kwanza, AI-gile si nini. Si kampuni changa, haiuzwi, na hakuna anayekusanya data yako. Ni ubao wa bure unaoendeshwa kwenye kompyuta yako, bila akaunti, bila vifuatiliaji na bila vidakuzi. Ni nini: mahali pamoja pa nadhifu pa kuona miradi yako yote ya AI ya kuandika msimbo kwa wakati mmoja, timu ya mawakala ikifanya kadi na wewe ukifanya maamuzi. Huunganisha kadi zinazohusiana, hurekebisha vichwa vilivyochanganyika, na hufuatilia jinsi msimbo unavyobaki mwepesi. Huzungumza takriban lugha 120, kuanzia Kiholanzi na Kiflemi hadi maharamia na Kiklingoni. Marafiki wanaweza kutumiana ujumbe, kwa faragha na kwa usimbaji. Ilijengwa na Rich na idadi kubwa ya mawakala wenye subira, hasa kwa kujitumia yenyewe. Iko kwenye pre-alpha iliyofungwa, kwa hiyo ina kasoro hapa na pale. Ukiona inavutia, omba kwa adabu na huenda ukaingia mapema."]}],"quips":{"1":"Neno moja. Jasiri. Labda jasiri kupita kiasi.","3":"Maneno matatu. Tayari ni ya kweli kuliko kurasa nyingi za bidhaa.","8":"Maneno manane. Bado ni mafupi kuliko stand-up.","21":"Kwa njia, urefu ni story points. Bila shaka ndivyo.","55":"Maneno hamsini na tano. Kadi mbili zimekamilika ulipokuwa unasoma hili.","144":"Hii ndiyo ndefu. Hakuna 233. Mawakala wamekwenda kulala."}},"timeline":{"first-idea.name":"Wazo la kwanza","first-idea.line":"Mazungumzo ya kwanza kabisa, kabla msimbo wowote haujakuwepo.","first-board.name":"Ubao wa kwanza","first-board.line":"Ubao unaofuatilia ujenzi wake wenyewe: kadi, safu, buruta na dondosha, miradi.","team-roles.name":"Timu na majukumu","team-roles.line":"Wasifu wa mawakala, violezo vya timu, nafasi na nani anafanya nini.","install.name":"Usakinishaji na matoleo","install.line":"Zip ambayo rafiki anaweza kusakinisha, kujisasisha, njia za matoleo na kurudi nyuma.","usage-saver.name":"Kiokoa matumizi","usage-saver.line":"Pima gharama za uendeshaji, weka msimbo mwepesi, okoa kikomo chako.","friends.name":"Marafiki na kushiriki","friends.line":"Ujumbe wa faragha, relay iliyosimbwa, mialiko, majukumu na miradi ya pamoja.","languages.name":"Lugha","languages.line":"Kila maandishi ya skrini kwenye faili la lugha, Kiholanzi na Kiflemi kwanza.","ai-tester.name":"Mjaribu wa AI","ai-tester.line":"Mjaribu hukagua kila makabidhiano kwanza na kuonyesha alichokiona.","website.name":"Tovuti","website.line":"aigile.lol, ukurasa wa utangulizi na ratiba hii.","streaming.name":"Gumzo na utiririshaji","streaming.line":"Discord, Twitch, OBS, hali ya mtiririshaji, GIF na emoji.","no-ai.name":"Toleo bila AI","no-ai.line":"Ubao kwa watu wanaoandika msimbo bila AI, na mbao za umma.","night-watch.name":"Mlinzi wa usiku","night-watch.line":"Mlinzi na Scrum Master huweka timu kwenye kazi ukiwa umelala.","p-more.name":"Mengine yote","p-more.line":"Mawazo madogo yanayosubiri zamu yake.","p-android.name":"Simu na Android","p-android.line":"Fikia ubao wako kutoka kwenye simu, kisha programu asilia ya Android.","p-release.name":"Alpha na zaidi","p-release.line":"Alpha iliyofungwa, tovuti hai, kisha beta.","p-languages.name":"Lugha zaidi","p-languages.line":"Zaidi ya lugha mia moja, na hali ya kuzama kwa wanaojifunza.","p-engines.name":"Injini zaidi za AI","p-engines.line":"Chagua Claude, Codex au Gemini kwa kila wakala.","p-pro.name":"Mazoea ya kitaalamu","p-pro.line":"Lebo za hatari, milango ya kuunganisha, kadi za matukio na vizuizi vya usalama.","p-self.name":"Kukutunza wewe","p-self.line":"Hali ya uchovu, vikumbusho vya kujitunza na 4:20.","p-servers.name":"Seva na ukuaji","p-servers.line":"Mipangilio ya seva ya kimataifa, majukumu na kupanga ukuaji.","p-livestream.name":"Ziada za utiririshaji","p-livestream.line":"Gumzo la Twitch, emoji maalum na mwonekano wa umma wa moja kwa moja."},"words":{"button":"📖 Maneno ya wasanidi","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Tafuta neno…","none":"Hakuna neno linalolingana.","close":"Funga","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Folda ya msimbo ya mradi na historia yake kamili ya commits, mara nyingi huhifadhiwa pia kwenye GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Mstari wa kazi uliotenganishwa kwenye msimbo, ili mabadiliko yafanywe bila kugusa toleo kuu.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Nakala iliyohifadhiwa ya msimbo, pamoja na maelezo mafupi ya kilichobadilika. Unaweza kurudi kwenye moja wakati wowote.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Kutuma nakala zilizohifadhiwa (commits) kutoka kompyuta hii hadi GitHub, ili ziwe na nakala rudufu na zishirikiwe."},{"id":"merge","g":"build","word":"Merge","text":"Kuunganisha mabadiliko ya branch kurudi kwenye toleo kuu."},{"id":"pr","g":"build","word":"Pull request","text":"Kuomba mabadiliko ya branch yakaguliwe na kuunganishwa kwenye toleo kuu.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Kupanga msimbo bila kubadilisha unachofanya: faili ndogo zaidi, majina wazi zaidi, marudio machache."},{"id":"bug","g":"build","word":"Bug","text":"Kitu kisichofanya kazi kama kinavyopaswa.","also":["bugs"]},{"id":"test","g":"build","word":"Jaribio","text":"Kujaribu kazi iliyokamilika ili kuona kama inafanya iliyoombwa, kabla ya kuikubali.","also":["test","tests","majaribio","jaribu","kujaribu","uijaribu"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Kuweka toleo jipya hewani, kwa mfano kwenye seva ambako watu wanalitumia."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Mawazo na kazi ambazo bado hazijapangwa. Hakuna kinachofanyiwa kazi huko hadi kihamie Za kufanya."},{"id":"sprint","g":"team","word":"Sprint","text":"Kipindi kifupi cha kazi (mara nyingi wiki moja au mbili) chenye seti iliyokubaliwa ya kadi za kumaliza.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Kikao cha haraka: kile ambacho kila mwanatimu amefanya, atakachofanya baadaye, na kinachomzuia.","also":["standup","stand-ups","standups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Ubao wenye safu wima (Za kufanya, Zinaendelea, Zimekamilika) ambapo kadi husogea kutoka kushoto kwenda kulia kazi inapoendelea."},{"id":"wip","g":"team","word":"Kikomo cha WIP","text":"Kazi inayoendelea: idadi ya juu ya kadi ambazo safu wima inapaswa kubeba, ili timu ikamilishe mambo kabla ya kuanza mengine.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Wakala","text":"AI inayofanya kazi yenyewe kwenye jukumu: husoma msimbo, hufanya mabadiliko, huendesha ukaguzi na kutoa taarifa.","also":["agent","agents","mawakala"]},{"id":"token","g":"team","word":"Tokeni","text":"Kipimo kinachotumika kuhesabu matumizi ya AI: takriban herufi chache za maandishi yanayosomwa au kuandikwa. Kadiri unavyotumia tokeni chache, ndivyo mpango wako unavyobaki zaidi.","also":["token","tokens","tokeni"]},{"id":"hook","g":"team","word":"Hook","text":"Amri ndogo inayojiendesha yenyewe wakati maalum, mf. kipindi cha AI kinapoanza, ili timu isikie maoni yako.","also":["hooks"]}]}};
